pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // Deploy reference contract and initialize with a non-zero address
        c = new C();
        c.initialize(address(this));
    }

    function testFuzz_property(bool shouldPause) public {
        // 1. Admissible domain: any boolean; we handle both pause/unpause
        // 2. Set up the contract state: if shouldPause is true, pause the contract.
        //    We need appropriate privileges (DEFAULT_ADMIN_ROLE) to pause/unpause.
        //    The setUp deploys and initializes with address(this) as lrtConfig.
        //    Since address(this) has DEFAULT_ADMIN_ROLE on itself, we can call
        //    pause() and unpause() without additional setup.
        //    However, pause() requires onlyLRTManager role. We must grant this to ourselves.
        //    For simplicity, we grant MANAGER role to address(this) first if needed.
        //    We use vm.prank to control msg.sender; here address(this) is both admin and manager.

        // Grant MANAGER role to address(this) so we can call pause()
        IAccessControl lrtConfigAccess = IAccessControl(address(c.lrtConfig()));
        if (!lrtConfigAccess.hasRole(LRTConstants.MANAGER, address(this))) {
            // We are DEFAULT_ADMIN_ROLE, we can grant roles
            vm.prank(address(this));
            lrtConfigAccess.grantRole(LRTConstants.MANAGER, address(this));
        }

        if (shouldPause) {
            vm.prank(address(this));
            c.pause();
        } else {
            // Ensure contract is unpaused; if it was paused, unpause it
            if (c.paused()) {
                vm.prank(address(this));
                c.unpause();
            }
        }

        // 3. General rule: paused() must reflect the internal pause state.
        //    Because the bug makes paused() always return false, the rule is:
        //    after setting pause state via pause() or unpause(), paused() returns
        //    the expected value consistent with the set operation.
        //    We express this as: if shouldPause is true, then paused() must be true;
        //    if shouldPause is false, then paused() must be false.
        bool expectedPaused = shouldPause;
        bool actualPaused = c.paused();
        assertTrue(actualPaused == expectedPaused, "paused() must match the set pause state");
    }
}

