pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address lrtConfigAddr) public {
        // Ensure the caller is not address(0) nor the test contract itself (the test contract is an EOA)
        vm.assume(caller != address(0) && caller != address(this));
        // The config address must be a contract implementing IAccessControl; deploy a minimal mock
        AccessControlMock mock = new AccessControlMock();
        address mockAddr = address(mock);
        // Initialize c with the mock as its LRT config; caller must be default admin for init
        // The mock's deployer (this test contract) has DEFAULT_ADMIN_ROLE, so we can grant roles.
        mock.grantRole(0x00, caller); // give caller default admin so it can call initialize
        vm.prank(caller);
        c.initialize(mockAddr);
        // Revoke admin from caller if we want to test non-admin; but we need to test both admin and manager cases.
        // The fuzzer will randomize whether caller has admin or manager role by setting roles on the mock.
        // We'll randomly decide (via fuzz) to grant MANAGER to caller.
        bytes32 MANAGER = keccak256("MANAGER");
        // Let the fuzzer decide whether caller has manager role by using the caller address bits
        // We'll grant manager role to caller if the last bit of caller is 1 (50% chance)
        bool giveManager = uint160(caller) & 1 == 1;
        if (giveManager) {
            // Grant manager role to caller (mock's deployer has admin, can grant)
            mock.grantRole(MANAGER, caller);
        }
        // Revoke default admin role from caller if the last-but-one bit is 0, else keep it
        bool keepAdmin = (uint160(caller) >> 1) & 1 == 1;
        if (!keepAdmin) {
            mock.revokeRole(0x00, caller);
        }
        // Now caller may or may not have admin, may or may not have manager.
        // Try to call updateLRTConfig as caller with a new valid config address (use the mock itself as new config)
        bool success;
        vm.prank(caller);
        try c.updateLRTConfig(mockAddr) {
            success = true;
        } catch {
            success = false;
        }
        // The reference contract should ONLY succeed if caller holds DEFAULT_ADMIN_ROLE (0x00).
        // Check that success matches hasRole(DEFAULT_ADMIN_ROLE, caller).
        bool hasAdmin = mock.hasRole(0x00, caller);
        assertTrue(success == hasAdmin);
    }
}

contract AccessControlMock {
    mapping(bytes32 => mapping(address => bool)) private _roles;
    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;

    constructor() {
        _roles[DEFAULT_ADMIN_ROLE][msg.sender] = true;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return _roles[role][account];
    }

    function grantRole(bytes32 role, address account) external {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "AccessControl: sender must be admin");
        _roles[role][account] = true;
    }

    function revokeRole(bytes32 role, address account) external {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "AccessControl: sender must be admin");
        _roles[role][account] = false;
    }
}

