        // Filter out zero addresses to avoid UtilLib.checkNonZeroAddress revert
        for (uint256 i = 0; i < len; i++) {
            vm.assume(nodeDelegatorContracts[i] != address(0));
        }

        // Initialize the contract with a valid lrtConfig address.
        // The lrtConfig must support isSupportedAsset and DEFAULT_ADMIN_ROLE for the caller,
        // but since we don't deploy a full LRTConfig, we use a simple mock that grants admin role
        // and marks the caller as admin. The fuzzed address will act as both the admin and the lrtConfig.
        // However, the initialize call expects a valid lrtConfig. To satisfy both roles, we deploy
        // a minimal mock that simply returns true for hasRole(DEFAULT_ADMIN_ROLE, any) and true for isSupportedAsset.
        // This avoids complex mock infrastructure while keeping the domain wide.
        MockLRTConfig config = new MockLRTConfig();
        c.initialize(address(config));

        // 2. The rule: adding delegators should succeed (not revert) when the resulting queue length
        //    is at most 10 (which is the default in the reference). In the buggy version, maxNodeDelegatorCount
        //    is 0, so any addition reverts with MaximumNodeDelegatorCountReached.
        //    We drive the addition using the admin prank.
        vm.prank(address(config)); // the mock grants admin to its own address

        bool success = true;
        try c.addNodeDelegatorContractToQueue(nodeDelegatorContracts) {
            // success
        } catch {
            success = false;
        }

        // 3. Assert that the addition does NOT revert (must succeed) under these conditions.
        //    Reference satisfies: success == true.
        //    Buggy violates: success == false for len >= 1.
        assertTrue(success);
    }
}

